 function sanitizeToolValue(value: unknown): unknown {
   if (typeof value === 'string') {
     return redactReviewText(value) ?? '';
   }
   if (Array.isArray(value)) {
     return value.map((item) => sanitizeToolValue(item));
   }
   if (value && typeof value === 'object') {
