    const stem = pathStem(file.path);
    if (stem) {
      maybeAddDeterministicSearchQuery(queries, seen, stem, file.path, 'dependency');
      if (queries.length >= MAX_DETERMINISTIC_SEARCH_QUERIES) {
        return queries;
