  if (queries.length === 0) {
    const fallbackStem = changedFiles.map((file) => pathStem(file.path)).find(Boolean);
    if (fallbackStem) {
      maybeAddDeterministicSearchQuery(queries, seen, fallbackStem, changedFiles[0]?.path ?? '.', 'dependency');
